<?php
declare(strict_types=1);require_once dirname(__DIR__).'/src/bootstrap.php';Auth::requireOwner();AgentService::reconcileRuntimeStates();$doctor=SystemDoctor::report();$agentStates=db()->query("SELECT a.slug,a.display_name,a.status,a.current_task_id,a.last_seen_at,a.last_error_code,(SELECT t.title FROM tasks t WHERE t.id=a.current_task_id) current_task_title FROM agents a ORDER BY FIELD(a.slug,'ramy','walid','ayman','emad'),a.id")->fetchAll();$providerStates=db()->query("SELECT p.provider_key,p.status,p.last_checked_at,p.last_error FROM providers p ORDER BY p.provider_key")->fetchAll();$queueNow=(int)db()->query("SELECT COUNT(*) FROM jobs WHERE state IN ('queued','waiting','running')")->fetchColumn();$failedNow=(int)db()->query("SELECT COUNT(*) FROM jobs WHERE state='failed' AND updated_at>=DATE_SUB(NOW(),INTERVAL 24 HOUR)")->fetchColumn();$heartbeat=(string)setting('runtime.worker_heartbeat_at','');$backs=db()->query("SELECT b.*,p.name project_name,t.title task_title FROM backups b JOIN projects p ON p.id=b.project_id LEFT JOIN tasks t ON t.id=b.task_id ORDER BY b.id DESC LIMIT 250")->fetchAll();$deploys=db()->query("SELECT d.*,p.name project_name,t.title task_title FROM deployments d JOIN projects p ON p.id=d.project_id LEFT JOIN tasks t ON t.id=d.task_id ORDER BY d.id DESC LIMIT 250")->fetchAll();$scans=db()->query("SELECT s.*,a.display_name agent_name FROM project_scans s LEFT JOIN agents a ON a.id=s.agent_id ORDER BY s.id DESC LIMIT 100")->fetchAll();$jobs=db()->query("SELECT j.*,a.display_name agent_name,p.name project_name,t.title task_title FROM jobs j LEFT JOIN agents a ON a.id=j.agent_id LEFT JOIN projects p ON p.id=j.project_id LEFT JOIN tasks t ON t.id=j.task_id ORDER BY j.id DESC LIMIT 150")->fetchAll();AdminUi::header('التشغيل والنسخ','operations');echo AdminUi::flash();?>
<div class="metric-grid"><?=AdminUi::stat('حالة النظام',$doctor['ok']?'سليم':'يحتاج مراجعة')?><?=AdminUi::stat('Queue الآن',$queueNow)?><?=AdminUi::stat('Failed 24h',$failedNow)?><?=AdminUi::stat('Worker heartbeat',$heartbeat?AdminUi::date($heartbeat):'لا يوجد')?></div>
<div class="grid"><section class="card span-6"><div class="card-title"><h2>حالة الفريق الفعلية</h2></div><?php foreach($agentStates as $a):?><div class="mini-item"><div class="grow"><b><?=e($a['display_name'])?></b><small><?=e($a['current_task_id']?'المهمة #'.$a['current_task_id'].(!empty($a['current_task_title'])?' — '.$a['current_task_title']:''):'بدون مهمة حالية')?> · <?=e(AdminUi::date($a['last_seen_at']))?><?=!empty($a['last_error_code'])?' · '.e(AdminUi::humanError((string)$a['last_error_code'])):''?></small></div><?=AdminUi::badge((string)$a['status'])?></div><?php endforeach?></section><section class="card span-6"><div class="card-title"><h2>الخدمات والاتصالات</h2><a href="health.php">اختبار فعلي</a></div><?php foreach($providerStates as $ps):?><div class="mini-item"><div class="grow"><b><?=e(AdminUi::provider((string)$ps['provider_key']))?></b><small><?=e($ps['last_checked_at']?AdminUi::date($ps['last_checked_at']):'لم يُختبر بعد')?><?=!empty($ps['last_error'])?' · '.e(AdminUi::humanError((string)$ps['last_error'])):''?></small></div><?=AdminUi::badge((string)($ps['status']?:'pending'))?></div><?php endforeach?></section></div>
<div class="toolbar"><form method="post" action="action.php"><?=AdminUi::csrf()?><input type="hidden" name="action" value="run_worker"><button class="btn">تشغيل عامل التشغيل الآن</button></form><form method="post" action="action.php"><?=AdminUi::csrf()?><input type="hidden" name="action" value="scan_projects"><button class="btn secondary">فهرسة Hostinger الآن</button></form><form method="post" action="action.php"><?=AdminUi::csrf()?><input type="hidden" name="action" value="install_worker_cron"><button class="btn secondary">تثبيت/تحقق التشغيل التلقائي</button></form></div>
<div class="grid"><section class="card span-6"><div class="card-title"><h2>النسخ ونقط الرجوع</h2><span class="muted small">الحذف الكامل محتاج نسخة كاملة أو نقطة رجوع متأكد منها.</span></div><div class="table-wrap"><table class="compact"><thead><tr><th>المشروع</th><th>النوع</th><th>المزود</th><th>الحالة</th><th>المرجع</th><th>التاريخ</th></tr></thead><tbody><?php foreach($backs as $b):?><tr><td><?=e($b['project_name'])?></td><td><?=e(AdminUi::label((string)$b['kind']))?></td><td><?=e(AdminUi::provider((string)$b['provider']))?></td><td><?=AdminUi::badge($b['status'])?></td><td class="mono"><?=e($b['location_ref']?:'—')?></td><td><?=e(AdminUi::date($b['created_at']))?></td></tr><?php endforeach?></tbody></table></div></section>
<section class="card span-6"><div class="card-title"><h2>عمليات النشر</h2></div><div class="table-wrap"><table class="compact"><thead><tr><th>المشروع</th><th>المهمة</th><th>الحالة</th><th>الإصدار</th><th>تحقق</th></tr></thead><tbody><?php foreach($deploys as $d):?><tr><td><?=e($d['project_name'])?></td><td><?=e($d['task_title']?:'—')?></td><td><?=AdminUi::badge($d['state'])?></td><td class="mono"><?=e($d['version_ref']?:'—')?></td><td><?=e(AdminUi::date($d['verified_at']))?></td></tr><?php endforeach?></tbody></table></div></section>
<section class="card span-6"><div class="card-title"><h2>فحوصات المشاريع</h2></div><div class="table-wrap"><table class="compact"><thead><tr><th>#</th><th>الوكيل</th><th>الحالة</th><th>مواقع</th><th>دومينات</th><th>قواعد البيانات</th><th>اكتمل</th></tr></thead><tbody><?php foreach($scans as $s):?><tr><td>#<?=$s['id']?></td><td><?=e($s['agent_name']?:'—')?></td><td><?=AdminUi::badge($s['state'])?></td><td><?=(int)$s['websites_found']?></td><td><?=(int)$s['domains_updated']?></td><td><?=(int)$s['databases_found']?></td><td><?=e(AdminUi::date($s['completed_at']))?></td></tr><?php endforeach?></tbody></table></div></section>
<section class="card span-6"><div class="card-title"><h2>طابور التشغيل</h2></div><div class="table-wrap"><table class="compact"><thead><tr><th>#</th><th>النوع</th><th>الوكيل</th><th>المشروع</th><th>المهمة</th><th>الحالة</th><th>المحاولات</th><th>تحكم</th></tr></thead><tbody><?php foreach($jobs as $j):?><tr><td>#<?=$j['id']?></td><td><?=e(AdminUi::label((string)$j['kind']))?></td><td><?=e($j['agent_name']?:'—')?></td><td><?=e($j['project_name']?:'—')?></td><td><?=e($j['task_title']?:'—')?></td><td><?=AdminUi::badge($j['state'])?></td><td><?=(int)$j['attempts']?>/<?=(int)$j['max_attempts']?></td><td><?php if(in_array($j['state'],['failed','waiting'],true)):?><form method="post" action="action.php" class="inline-form"><?=AdminUi::csrf()?><input type="hidden" name="action" value="job_retry"><input type="hidden" name="job_id" value="<?=$j['id']?>"><button class="btn secondary small-btn">إعادة للطابور</button></form><?php else:?>—<?php endif?></td></tr><?php endforeach?></tbody></table></div></section></div><?php AdminUi::footer();
